public class MinHeapTest {
    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    private static void assertFalse(boolean condition, String message) {
        assertTrue(!condition, message);
    }

    private static void assertEquals(int actual, int expected, String message) {
        if (actual != expected) {
            throw new AssertionError(message);
        }
    }

    private static void assertThrowsIllegalArgument(Runnable action, String message) {
        boolean rejected = false;
        try {
            action.run();
        } catch (IllegalArgumentException expected) {
            rejected = true;
        }
        assertTrue(rejected, message);
    }

    private static void runSanityChecks() {
        MinHeap empty = new MinHeap(0);
        assertEquals(empty.peek(), MinHeap.EMPTY_VALUE, "Empty heap should report Integer.MAX_VALUE");
        assertEquals(empty.poll(), MinHeap.EMPTY_VALUE, "Empty heap extraction should report Integer.MAX_VALUE");

        MinHeap heap = new MinHeap(4);
        assertEquals(heap.capacity(), 4, "Capacity accessor should match constructor input");
        assertTrue(heap.offer(8), "Expected insert to succeed");
        assertTrue(heap.offer(3), "Expected insert to succeed");
        assertTrue(heap.offer(5), "Expected insert to succeed");
        heap.updateKey(0, 1);
        assertEquals(heap.peek(), 1, "Key update should restore heap order");
        assertEquals(heap.size(), 3, "Heap size should reflect inserted elements");
        assertTrue(heap.offer(9), "Expected final insert to succeed before reaching capacity");
        assertFalse(heap.offer(11), "Insert should fail once the heap reaches capacity");

        heap.removeAtIndex(1);
        assertEquals(heap.size(), 3, "Delete should reduce heap size");
        assertEquals(heap.peek(), 1, "Delete should preserve the minimum element");

        assertThrowsIllegalArgument(
            () -> heap.decreaseKey(0, 99),
            "decreaseKey should reject larger values"
        );
        assertThrowsIllegalArgument(
            () -> heap.increaseKey(0, 0),
            "increaseKey should reject smaller values"
        );
    }

    public static void main(String[] args) {
        runSanityChecks();

        MinHeap h = new MinHeap(11);
        h.offer(3);
        h.offer(2);
        h.removeAtIndex(1);
        h.offer(15);
        h.offer(5);
        h.offer(4);
        h.offer(45);
        System.out.print(h.poll() + " ");
        System.out.print(h.peek() + " ");

        h.decreaseKey(2, 1);
        System.out.print(h.peek());
    }
}

public final class MinHeap {

    public static final int EMPTY_VALUE = Integer.MAX_VALUE;

    private final int[] elements;

    private final int capacity;

    private int size;

    public MinHeap(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Heap capacity must be non-negative");
        }
        capacity = n;
        elements = new int[capacity];
        size = 0;
    }

    private int parentIndex(int index) {
        return (index - 1) / 2;
    }

    private int leftChildIndex(int index) {
        return 2 * index + 1;
    }

    private int rightChildIndex(int index) {
        return 2 * index + 2;
    }

    private boolean isFull() {
        return size == capacity;
    }

    private boolean isEmptyHeap() {
        return size == 0;
    }

    private void validateIndex(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException(
                "Index " + index + " is outside the heap size " + size
            );
        }
    }

    private void bubbleUp(int index) {
        int value = elements[index];
        while (index != 0) {
            int parent = parentIndex(index);
            if (elements[parent] <= value) {
                break;
            }
            elements[index] = elements[parent];
            index = parent;
        }
        elements[index] = value;
    }

    private void bubbleDown(int index) {
        int value = elements[index];
        while (true) {
            int left = leftChildIndex(index);
            if (left >= size) {
                break;
            }

            int right = rightChildIndex(index);
            int smallestChild = left;
            if (right < size && elements[right] < elements[left]) {
                smallestChild = right;
            }

            if (elements[smallestChild] >= value) {
                break;
            }

            elements[index] = elements[smallestChild];
            index = smallestChild;
        }
        elements[index] = value;
    }

    private void updateKeyInternal(int index, int newVal) {
        int oldVal = elements[index];
        if (newVal == oldVal) {
            return;
        }

        elements[index] = newVal;
        if (newVal < oldVal) {
            bubbleUp(index);
        } else {
            bubbleDown(index);
        }
    }

    private void validateKeyMovement(int index, int newVal, boolean decreasing) {
        int currentValue = elements[index];
        if (decreasing ? newVal > currentValue : newVal < currentValue) {
            throw new IllegalArgumentException(
                decreasing
                    ? "New value must not be greater than the current value"
                    : "New value must not be less than the current value"
            );
        }
    }

    private void repairHeapAt(int index) {
        if (index > 0 && elements[index] < elements[parentIndex(index)]) {
            bubbleUp(index);
        } else {
            bubbleDown(index);
        }
    }

    private void removeAtInternal(int index) {
        validateIndex(index);

        int lastIndex = size - 1;
        if (index == lastIndex) {
            size--;
            return;
        }

        elements[index] = elements[lastIndex];
        size--;
        repairHeapAt(index);
    }

    public boolean offer(int key) {
        if (isFull()) {
            return false;
        }

        elements[size] = key;
        bubbleUp(size);
        size++;
        return true;
    }

    public void decreaseKey(int key, int newVal) {
        validateIndex(key);
        validateKeyMovement(key, newVal, true);
        updateKeyInternal(key, newVal);
    }

    public int peek() {
        if (isEmptyHeap()) {
            return EMPTY_VALUE;
        }
        return elements[0];
    }

    public int poll() {
        if (isEmptyHeap()) {
            return EMPTY_VALUE;
        }

        int root = elements[0];
        removeAtInternal(0);
        return root;
    }

    public void increaseKey(int key, int newVal) {
        validateIndex(key);
        validateKeyMovement(key, newVal, false);
        updateKeyInternal(key, newVal);
    }

    public int size() {
        return size;
    }

    public boolean isEmpty() {
        return isEmptyHeap();
    }

    public void updateKey(int key, int newVal) {
        validateIndex(key);
        updateKeyInternal(key, newVal);
    }

    public void removeAtIndex(int key) {
        removeAtInternal(key);
    }

    public int capacity() {
        return capacity;
    }
}

